// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;

    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1 ether);

        Attacker att = new Attacker();
        att.setTarget(address(c));

        vm.deal(address(att), amount);
        att.depositAndWithdraw(amount);

        // Rule: after a completed withdrawBalance, the caller has received
        // exactly its deposited balance and the contract holds no ETH.
        assertTrue(
            att.totalReceived() == amount && address(c).balance == 0,
            "exactly one payout of the deposited balance"
        );
    }
}

contract Attacker {
    Reentrance private c;
    bool private entered;
    uint256 public totalReceived;

    function setTarget(address t) external { c = Reentrance(t); }

    function depositAndWithdraw(uint256 amount) external {
        c.addToBalance{value: amount}();
        c.withdrawBalance();
    }

    receive() external payable {
        totalReceived += msg.value;
        if (!entered) {
            entered = true;
            c.withdrawBalance();
        }
    }
}
